package external

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os/exec"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// defaultRunTimeout is the maximum time an external binary call may take when
// the caller provides a context without a deadline.
var defaultRunTimeout = 30 * time.Second //nolint:gochecknoglobals // overridable for testing

// Agent implements agent.Agent by delegating to an external binary.
// Each method invokes a subcommand on the binary and parses the JSON response.
type Agent struct {
	binaryPath string
	info       *InfoResponse
}

// New creates an Agent by calling the binary's "info" subcommand
// to cache its metadata. Returns an error if the binary cannot be invoked or returns
// invalid/incompatible protocol data. The provided context bounds the "info" call;
// pass a context with a deadline to limit how long discovery waits for each binary.
func New(ctx context.Context, binaryPath string) (*Agent, error) {
	ea := &Agent{binaryPath: binaryPath}

	stdout, err := ea.run(ctx, nil, "info")
	if err != nil {
		return nil, fmt.Errorf("info: %w", err)
	}

	var info InfoResponse
	if err := json.Unmarshal(stdout, &info); err != nil {
		return nil, fmt.Errorf("info: invalid JSON: %w", err)
	}

	if info.ProtocolVersion != ProtocolVersion {
		return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
			info.ProtocolVersion, ProtocolVersion)
	}

package external

import (
	"context"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const binaryPrefix = "entire-agent-"

// DiscoverAndRegister scans $PATH for executables matching "entire-agent-<name>",
// calls their "info" subcommand, and registers them in the agent registry.
// Binaries whose name conflicts with an already-registered agent are skipped.
// Errors during discovery are logged but do not prevent other agents from loading.
func DiscoverAndRegister(ctx context.Context) {
	if !settings.IsExternalAgentsEnabled(ctx) {
		logging.Debug(ctx, "external agent discovery disabled (external_agents not enabled in settings)")
		return
	}

	pathEnv := os.Getenv("PATH")
	if pathEnv == "" {
		return
	}

	// Collect already-registered names to avoid conflicts.
	registered := make(map[types.AgentName]bool)
	for _, name := range agent.List() {
		registered[name] = true
	}

	seen := make(map[string]bool) // deduplicate binaries across PATH dirs
	for _, dir := range filepath.SplitList(pathEnv) {
		matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
		if err != nil {
			continue // skip unreadable directories
		}
		for _, binPath := range matches {
			name := filepath.Base(binPath)
			if seen[name] {
				continue
			}
			seen[name] = true

			agentName := types.AgentName(strings.TrimPrefix(name, binaryPrefix))
			if registered[agentName] {
				logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
					slog.String("binary", name),
					slog.String("agent", string(agentName)))
				continue
			}

			finfo, err := os.Stat(binPath) //nolint:gosec // PATH entries are trusted
			if err != nil || finfo.IsDir() {
				continue
			}
			// Check executable bit (on Unix)
			if finfo.Mode()&0o111 == 0 {
				continue
			}

			ea, err := New(ctx, binPath)
			if err != nil {
				logging.Debug(ctx, "skipping external agent (info failed)",
					slog.String("binary", binPath),
					slog.String("error", err.Error()))
				continue
			}

			// Wrap with capability interfaces and register
			wrapped, err := Wrap(ea)
			if err != nil {
				logging.Debug(ctx, "skipping external agent (wrap failed)",
					slog.String("binary", binPath),
					slog.String("error", err.Error()))
				continue
			}
			agent.Register(agentName, func() agent.Agent {
				return wrapped
			})
			registered[agentName] = true

			logging.Debug(ctx, "registered external agent",
				slog.String("name", string(agentName)),
				slog.String("type", string(ea.Type())),
				slog.String("binary", binPath))
		}
	}
}

	// Find newly selected agents (not previously installed)
	var newAgents []agent.Agent
	for _, name := range selectedAgentNames {
		if _, wasInstalled := installedSet[types.AgentName(name)]; wasInstalled {
			continue
		}
		ag, err := agent.Get(types.AgentName(name))
		if err != nil {
			return fmt.Errorf("failed to get agent %s: %w", name, err)
		}
		newAgents = append(newAgents, ag)
	}

	if len(newAgents) == 0 {
		fmt.Fprintln(w, "No new agents selected.")
		return nil
	}

	// Install hooks for newly selected agents only
	for _, ag := range newAgents {
		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
		}
	}

	newTypes := make([]string, 0, len(newAgents))
	for _, ag := range newAgents {
		newTypes = append(newTypes, string(ag.Type()))
	}
	fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(newTypes, ", "))

	return nil
}

func newSetupCmd() *cobra.Command {
	var opts EnableOptions
	var agentName string
	var removeAgentName string
	var externalAgents bool

	cmd := &cobra.Command{
		Use:   "configure",
		Short: "Configure Entire in current repository",
		Long: `Configure Entire with session tracking for your AI agent workflows.

On first run, this configures Entire and installs agent hooks.
On subsequent runs, it lets you enable more agents.

Use --remove to remove a specific agent's hooks:
  entire configure --remove claude-code`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			if _, err := paths.WorktreeRoot(ctx); err != nil {
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire configure' from within a git repository.")
				return NewSilentError(errors.New("not a git repository"))
			}

			if cmd.Flags().Changed("external-agents") {
				opts.ExternalAgents = &externalAgents
			}

			// Discover external agent plugins early so they're available
			// for --agent, --remove, and interactive selection.
			external.DiscoverAndRegister(ctx)

			// Remove agent mode
			if removeAgentName != "" {
				return runRemoveAgent(ctx, cmd.OutOrStdout(), removeAgentName)
			}

			// Non-interactive --agent mode
			if cmd.Flags().Changed(agentFlagName) && agentName == "" {
				printMissingAgentError(cmd.ErrOrStderr())
				return NewSilentError(errors.New("missing agent name"))
			}
			if agentName != "" {
				ag, err := agent.Get(types.AgentName(agentName))
				if err != nil {
					printWrongAgentError(cmd.ErrOrStderr(), agentName)
					return NewSilentError(errors.New("wrong agent name"))
				}
				return setupAgentHooksNonInteractive(ctx, cmd.OutOrStdout(), ag, opts)
			}

			// If already set up, show agents and let user add more
			if settings.IsSetUpAny(ctx) {
				return runAddAgents(ctx, cmd.OutOrStdout(), opts)
			}

			// Fresh repo — run full setup flow
			return runSetupFlow(ctx, cmd.OutOrStdout(), opts)
		},
	}

	cmd.Flags().BoolVar(&opts.LocalDev, "local-dev", false, "Use go run instead of entire binary for hooks")
	cmd.Flags().MarkHidden("local-dev") //nolint:errcheck,gosec // flag is defined above
	cmd.Flags().BoolVar(&opts.UseLocalSettings, "local", false, "Write settings to .entire/settings.local.json instead of .entire/settings.json")
	cmd.Flags().BoolVar(&opts.UseProjectSettings, "project", false, "Write settings to .entire/settings.json even if it already exists")
	cmd.Flags().StringVar(&agentName, agentFlagName, "", "Enable a specific agent (e.g., "+strings.Join(agent.StringList(), ", ")+")")
	cmd.Flags().StringVar(&removeAgentName, "remove", "", "Remove a specific agent's hooks (e.g., "+strings.Join(agent.StringList(), ", ")+")")
	cmd.Flags().BoolVarP(&opts.ForceHooks, "force", "f", false, "Force reinstall hooks (removes existing Entire hooks first)")
	cmd.Flags().BoolVar(&opts.SkipPushSessions, "skip-push-sessions", false, "Disable automatic pushing of session logs on git push")
	cmd.Flags().BoolVar(&opts.Telemetry, "telemetry", true, "Enable anonymous usage analytics")
	cmd.Flags().BoolVar(&opts.AbsoluteGitHookPath, "absolute-git-hook-path", false, "Embed full binary path in git hooks (for GUI git clients that don't source shell profiles)")
	cmd.Flags().BoolVar(&externalAgents, "external-agents", false, "Enable external agent plugin discovery (entire-agent-* binaries on $PATH)")

	// Provide a helpful error when --agent is used without a value
	defaultFlagErr := cmd.FlagErrorFunc()
	cmd.SetFlagErrorFunc(func(c *cobra.Command, err error) error {
		var valErr *pflag.ValueRequiredError
		if errors.As(err, &valErr) && valErr.GetSpecifiedName() == agentFlagName {
			printMissingAgentError(c.ErrOrStderr())
			return NewSilentError(errors.New("missing agent name"))
		}
		return defaultFlagErr(c, err)
	})

	return cmd
}

